      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.deepEqual(result, []);
});

test('vatSummary filters by status: ignores draft invoices', () => {
  const invoices = [
    {
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 20 }],
