});

test('vatSummary includes issued invoices', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 20);
  assert.equal(result[0].base, 10000);
  assert.equal(result[0].vat, 2000);
});

test('vatSummary includes partially_paid invoices', () => {
  const invoices = [
    {
      status: 'partially_paid',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 20);
});

test('vatSummary includes paid invoices', () => {
  const invoices = [
    {
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 20);
});

test('vatSummary calculates base correctly without discount', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 5, unitPrice: 2000, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result[0].base, 10000);
});

test('vatSummary calculates base correctly with discount', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 5, unitPrice: 2000, discountPercent: 10, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  // 5 * 2000 = 10000, discount = 1000, base = 9000
  assert.equal(result[0].base, 9000);
});

test('vatSummary calculates VAT correctly', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  // base = 10000, vat = 10000 * 0.20 = 2000
  assert.equal(result[0].vat, 2000);
