test('vatSummary handles zero VAT rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result[0].rate, 0);
  assert.equal(result[0].base, 10000);
  assert.equal(result[0].vat, 0);
});

test('vatSummary handles missing vatRate defaults to 0', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result[0].rate, 0);
  assert.equal(result[0].vat, 0);
});

test('vatSummary groups by VAT rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 10000, vatRate: 20 },
        { qty: 1, unitPrice: 5000, vatRate: 20 },
      ],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 20);
  assert.equal(result[0].base, 15000);
