});

test('vatSummary handles multiple VAT rates', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 10000, vatRate: 20 },
        { qty: 1, unitPrice: 5000, vatRate: 5 },
      ],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 20);
  assert.equal(result[1].rate, 5);
});

test('vatSummary sorts by rate descending', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 10000, vatRate: 5 },
        { qty: 1, unitPrice: 10000, vatRate: 20 },
        { qty: 1, unitPrice: 10000, vatRate: 10 },
      ],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 3);
  assert.equal(result[0].rate, 20);
  assert.equal(result[1].rate, 10);
  assert.equal(result[2].rate, 5);
});

test('vatSummary aggregates across multiple invoices', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 5000, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].base, 15000);
  assert.equal(result[0].vat, 3000);
});

test('vatSummary aggregates across multiple statuses', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
    {
      status: 'partially_paid',
      lines: [{ qty: 1, unitPrice: 5000, vatRate: 20 }],
    },
    {
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 5000, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].base, 20000);
  assert.equal(result[0].vat, 4000);
});

test('vatSummary with discount on multiple lines', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 20 },
        { qty: 1, unitPrice: 10000, discountPercent: 20, vatRate: 20 },
      ],
    },
  ];

  const result = vatSummary(invoices);
  // Line 1: 10000 - 1000 = 9000
  // Line 2: 10000 - 2000 = 8000
  // Total base: 17000, vat: 3400
  assert.equal(result[0].base, 17000);
  assert.equal(result[0].vat, 3400);
});

test('vatSummary returns copies, not references', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
  ];

  const result1 = vatSummary(invoices);
  const result2 = vatSummary(invoices);

  assert.notStrictEqual(result1, result2);
  assert.notStrictEqual(result1[0], result2[0]);
});

test('vatSummary handles empty invoice array', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary ignores invoices with draft status', () => {
  const invoices = [
    {
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].base, 10000);
});

test('vatSummary preserves all required fields', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
  ];

  const result = vatSummary(invoices);
  const item = result[0];
  assert.equal(typeof item.rate, 'number');
  assert.equal(typeof item.base, 'number');
  assert.equal(typeof item.vat, 'number');
});

test('vatSummary does not mutate input array', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 20 }],
    },
  ];

  const originalLength = invoices.length;
  vatSummary(invoices);

  assert.equal(invoices.length, originalLength);
});

test('lateFee returns 0 when invoice is not overdue', () => {
  const invoice = {
    dueDate: '2024-12-25',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  assert.equal(fee, 0);
});

test('lateFee returns 0 when due date equals asOf', () => {
  const invoice = {
    dueDate: '2024-12-20',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  assert.equal(fee, 0);
});

test('lateFee calculates correctly for 1 day overdue', () => {
  const invoice = {
    dueDate: '2024-12-19',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // 10000 * 0.0004 * 1 = 4
  assert.equal(fee, 4);
});

test('lateFee calculates correctly for 10 days overdue', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // 10000 * 0.0004 * 10 = 40
  assert.equal(fee, 40);
});

test('lateFee accounts for partial payments', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'partially_paid',
    lines: [{ qty: 1, unitPrice: 10000 }],
    payments: [{ amount: 5000, date: '2024-12-15' }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // 5000 (due) * 0.0004 * 10 = 20
  assert.equal(fee, 20);
});

test('lateFee returns 0 when invoice is fully paid', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'paid',
    lines: [{ qty: 1, unitPrice: 10000 }],
    payments: [{ amount: 10000, date: '2024-12-15' }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // balanceDue = 0, so fee = 0
  assert.equal(fee, 0);
});

test('lateFee calculates with VAT included in total', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 20 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // 12000 (10000 + 2000 VAT) * 0.0004 * 10 = 48
  assert.equal(fee, 48);
});

test('lateFee handles long overdue periods', () => {
  const invoice = {
    dueDate: '2024-01-01',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  const fee = lateFee(invoice, '2024-12-31');
  // 365 days overdue (Jan 1 to Dec 31, 2024 is a leap year)
  // 10000 * 0.0004 * 365 = 1460
  assert.equal(fee, 1460);
});

test('lateFee handles invoices with multiple lines', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [
      { qty: 1, unitPrice: 5000 },
      { qty: 1, unitPrice: 5000 },
    ],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // 10000 * 0.0004 * 10 = 40
  assert.equal(fee, 40);
});

test('lateFee handles invoice with discount', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 10 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // 9000 (after discount) * 0.0004 * 10 = 36
  assert.equal(fee, 36);
});

test('lateFee rounds to cents correctly', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 1111 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // 1111 * 0.0004 * 10 = 4.444, rounded to 4
  assert.equal(fee, 4);
});

test('lateFee with fractional days (should use floor)', () => {
  // This tests that we use Math.floor for day calculation
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  // Same date should give 0 days
  const fee = lateFee(invoice, '2024-12-10');
  assert.equal(fee, 0);
});

test('lateFee with small amounts', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 100 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  // 100 * 0.0004 * 10 = 0.4, rounded to 0
  assert.equal(fee, 0);
});

test('lateFee handles zero balance due', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
    payments: [{ amount: 10000, date: '2024-12-15' }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  assert.equal(fee, 0);
});

test('lateFee calculates consistently with overdueInvoices daysOverdue', () => {
  const invoice = {
    number: 'INV-001',
    customerId: 'C-001',
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  const overdueResult = overdueInvoices([invoice], '2024-12-20');
  const feeResult = lateFee(invoice, '2024-12-20');

  // They should use the same day calculation
  assert.equal(overdueResult[0].daysOverdue, 10);
  // 10000 * 0.0004 * 10 = 40
  assert.equal(feeResult, 40);
});

test('lateFee returns positive number', () => {
  const invoice = {
    dueDate: '2024-12-10',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 10000 }],
  };

  const fee = lateFee(invoice, '2024-12-20');
  assert.ok(fee >= 0);
});

